if ($input.all().length === 0) { return []; }
const norm = $('Normalize Event').item.json;
const existingRows = $('Lookup Source Row').all().map(i => i.json).filter(r => r && r.id !== undefined);
const before = existingRows.length > 0 ? existingRows[0] : null;
return [{ json: { ...norm, before } }];

if ($input.all().length === 0) { return []; }
const norm = $('Normalize Event').item.json;
const attempt = $json.attempt ?? 0;
return [{ json: {
  attempt,
  maxRetries: 3,
  baseDelaySec: 2,
  targetSystem: norm.targetSystem,
  sourceSystem: norm.sourceSystem,
  contact: {
    externalId: norm.externalId, name: norm.name, email: norm.email,
    phone: norm.phone, sourceUpdatedAt: norm.sourceUpdatedAt,
  },
  simulateFailure: norm.simulateFailure,
  idempotencyKey: norm.idempotencyKey,
} }];

if ($input.all().length === 0) { return []; }
const prep = $('Prepare Adapter Call').item.json;
const attempt = prep.attempt;
const base = prep.baseDelaySec;
const waitSec = Math.round((base * Math.pow(2, attempt) + Math.random()) * 100) / 100;
const errItem = $input.first() ? $input.first().json : {};
const lastError = (errItem && (errItem.error && errItem.error.message || errItem.error || errItem.message)) || 'unknown error';
return [{ json: {
  attempt: attempt + 1,
  maxRetries: prep.maxRetries,
  baseDelaySec: prep.baseDelaySec,
  targetSystem: prep.targetSystem,
  sourceSystem: prep.sourceSystem,
  contact: prep.contact,
  simulateFailure: prep.simulateFailure,
  idempotencyKey: prep.idempotencyKey,
  waitSec,
  lastError,
} }];

if ($input.all().length === 0) { return []; }
const prep = $('Prepare Adapter Call').item.json;
const errItem = $input.first() ? $input.first().json : {};
const lastError = (errItem && (errItem.error && errItem.error.message || errItem.error || errItem.message)) || 'unknown error';
const dlqId = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : (Date.now() + '-' + Math.random().toString(36).slice(2));
return [{ json: {
  dlqId,
  system: prep.targetSystem,
  payload: JSON.stringify({ targetSystem: prep.targetSystem, sourceSystem: prep.sourceSystem, contact: prep.contact, simulateFailure: prep.simulateFailure, idempotencyKey: prep.idempotencyKey }),
  attempts: prep.attempt,
  lastError,
  firstFailedAt: new Date().toISOString(),
  lastAttemptAt: new Date().toISOString(),
  status: 'pending',
  externalId: prep.contact.externalId,
} }];

if ($input.all().length === 0) { return []; }
const items = $input.all().map(i => i.json);
const rows = items.filter(r => r && r.dlqId !== undefined);
if (rows.length === 0) {
  return [{ json: { empty: true, drained: 0 } }];
}
return rows.map(r => ({ json: r }));

if ($input.all().length === 0) { return []; }
const row = $('Normalize Replay Batch').item.json;
const result = $input.first() ? $input.first().json : {};
return [{ json: {
  dlqId: row.dlqId,
  externalId: result.externalId,
  targetSystem: result.targetSystem,
  sourceSystem: result.sourceSystem,
  idempotencyKey: result.idempotencyKey,
  before: result.before,
  after: result.after,
  action: result.action,
  outcome: 'replayed_success',
} }];

if ($input.all().length === 0) { return []; }
const row = $('Normalize Replay Batch').item.json;
const errItem = $input.first() ? $input.first().json : {};
const lastError = (errItem && (errItem.error && errItem.error.message || errItem.error || errItem.message)) || 'unknown error';
const parsed = JSON.parse(row.payload);
return [{ json: {
  dlqId: row.dlqId,
  externalId: parsed.contact.externalId,
  targetSystem: row.system,
  idempotencyKey: parsed.idempotencyKey || '',
  attempts: (row.attempts || 0) + 1,
  lastError,
  lastAttemptAt: new Date().toISOString(),
  outcome: 'replayed_failure_requeued',
} }];

if ($input.all().length === 0) { return []; }
const items = $input.all().map(i => i.json);
const succeeded = items.filter(i => i.outcome === 'replayed_success');
const requeued = items.filter(i => i.outcome === 'replayed_failure_requeued');
return [{ json: {
  status: 'replay_complete',
  drained: items.length,
  succeeded: succeeded.length,
  requeued: requeued.length,
  details: items,
} }];
